    await open(id); await sleep(5000); await watchM(); mark();
    const target = kind === 'plain' ? (e) => e.v.startsWith('plainb') : kind === 'headline' ? (e) => e.v === 'hb' : (e) => e.v.includes('hbody');
    const edsBefore = await edsM();
