    const focusV = await b.ev(`(()=>{const a=document.activeElement;return a?(a.tagName+':'+(a.value??'')).slice(0,80):null})()`);
    const addTxt = kind === 'plain' ? ' plus p' : kind === 'headline' ? ' plus t' : ' plus h';
    await typeText(addTxt, 90); await sleep(1000);
